import { faqs } from '@/data/community';

export function Faq() {
  return (
    <section id="preguntas" className="faq-section section-rail" aria-labelledby="faq-heading">
      <div className="section-label"><span>05 / PREGUNTAS FRECUENTES</span><span>HABLEMOS CON CLARIDAD</span></div>
      <div className="faq-layout">
        <div>
          <h2 id="faq-heading">Antes de<br/>hacer <em>click.</em></h2>
          <p>Colaborar empieza por entendernos.<br/>Estas son algunas buenas preguntas.</p>
        </div>
        <div className="faq-list">
          {faqs.map(faq => (
            <article key={faq.question} className="faq-item">
              <h3>{faq.question}</h3>
              <p>{faq.answer}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

