.page-title { font-size: clamp(48px,7vw,104px); line-height: .98; font-weight: 500; letter-spacing: -.06em; }
.page-title em { font-family: 'Instrument Serif', serif; font-style: italic; font-weight: 400; font-size: 1.1em; }
.page-title .click-dot { color: #479f73; }
.page-hero-bottom { display: grid; grid-template-columns: 1fr 340px; gap: 60px; align-items: end; padding: 30px 0 50px; border-bottom: 1px solid var(--line); }
.page-hero-intro { font-size: 15px; color: var(--quiet); line-height: 1.85; max-width: 560px; }
.page-hero-ctas { display: grid; gap: 12px; }
.prepare-section { padding-top: 70px; }
.prepare-grid { display: grid; grid-template-columns: 1.3fr 1fr; gap: 8%; margin-top: 40px; align-items: start; }
.prepare-checklist h3 { font-size: 20px; font-weight: 500; letter-spacing: -.5px; margin-bottom: 22px; }
.prepare-checklist ul { list-style: none; padding: 0; display: grid; gap: 14px; }
.prepare-checklist li { display: flex; gap: 12px; align-items: center; font-size: 14px; }
.prepare-checklist li svg { color: #407757; flex-shrink: 0; }
.guide-card { padding: 32px; border: 1px solid var(--line); background: var(--paper); display: flex; flex-direction: column; gap: 14px; }
.guide-card-aporte { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.guide-card-kicker { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 10px; letter-spacing: 1px; color: var(--quiet); }
.guide-card-aporte .guide-card-kicker { color: var(--mint); }
.guide-card h3 { font-size: 26px; font-weight: 500; letter-spacing: -1px; }
.guide-card p { font-size: 13px; line-height: 1.8; color: var(--quiet); }
.guide-card-aporte p { color: var(--dark-muted); }
.guide-card .button { width: 100%; }
.guide-card small { font-size: 10px; line-height: 1.7; color: var(--quiet); }
.guide-card-aporte small { color: var(--dark-muted); }
.next-steps-section { padding-top: 28px; }
.next-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; margin-top: 40px; }
.next-card { display: flex; flex-direction: column; gap: 14px; padding: 32px; border: 1px solid var(--line); background: var(--paper); transition: border-color 180ms ease, transform 180ms ease; }
.next-card:hover { border-color: #9cb6a3; transform: translateY(-3px); }
.next-card > span { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 10px; letter-spacing: 1px; color: var(--quiet); }
.next-card h3 { font-size: 26px; font-weight: 500; letter-spacing: -1px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.next-card p { font-size: 13px; line-height: 1.8; color: var(--quiet); }
.next-card-mint { background: var(--mint); border-color: var(--mint); }
.next-card-mint > span, .next-card-mint p { color: #2c5a45; }
.pilot-section { padding-top: 20px; }
.pilot-form-card { max-width: 760px; border: 1px solid var(--line); background: var(--paper); padding: 40px; }
.form-success-card { background: #e5eddf; border-color: #9cb6a3; display: flex; flex-direction: column; gap: 12px; }
.form-success-card .status-dot { background: #398d65; }
.form-field { display: flex; flex-direction: column; gap: 8px; margin-bottom: 22px; }
.form-label { font-size: 12px; font-weight: 700; letter-spacing: .3px; }
.form-label .req { color: #c8821a; }
.form-input, .form-select, .form-textarea { width: 100%; padding: 13px 15px; border: 1px solid var(--line); border-radius: 5px; background: #fff; font: inherit; font-size: 14px; color: var(--ink); transition: border-color 180ms ease; }
.form-input:focus, .form-select:focus, .form-textarea:focus { outline: none; border-color: #407757; box-shadow: 0 0 0 3px #97e8be55; }
.form-textarea { min-height: 120px; resize: vertical; }
.form-field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.form-checkbox-field { display: flex; gap: 12px; align-items: start; margin: 8px 0 26px; }
.form-checkbox { width: 18px; height: 18px; margin-top: 3px; accent-color: #338663; flex-shrink: 0; }
.form-checkbox-field label { font-size: 13px; line-height: 1.7; color: var(--quiet); }
.form-error { font-size: 12px; color: #b3261e; }
.form-error-general { margin-bottom: 18px; padding: 12px; background: #fdeceb; border-radius: 5px; }
.form-note { font-size: 11px; line-height: 1.7; color: var(--quiet); margin-top: 18px; }
.business-future { font-size: 12px; line-height: 1.8; color: var(--dark-muted); margin-top: 22px; max-width: 390px; }
.business-future strong { color: var(--mint); }
.site-footer { padding: 0 5.5%; background: #eaf0e6; }

.not-found { padding: 40px 5.5% 0; min-height: calc(100dvh - 104px); display: flex; flex-direction: column; justify-content: center; max-width: 1800px; margin: auto; }
.not-found-inner { display: flex; flex-direction: column; gap: 24px; padding: 50px 0; }
.not-found-title { font-size: clamp(48px, 8vw, 116px); line-height: .98; font-weight: 500; letter-spacing: -.06em; }
.not-found-text { font-size: 15px; color: var(--quiet); line-height: 1.85; max-width: 520px; }
.not-found-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 8px; }
.not-found-actions .button { min-width: 200px; }
.not-found-wordmark { margin-top: 18px; }
.footer-invite { display: flex; align-items: center; justify-content: space-between; gap: 35px; padding: 55px 0; border-bottom: 1px solid #c8d2c4; }
.footer-invite p { font-size: clamp(28px,3.7vw,52px); letter-spacing: -1.8px; line-height: 1.25; }
.footer-invite > a { width: 85px; height: 85px; border: 1px solid var(--ink); border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; transition: background 180ms ease; }
.footer-invite > a:hover { background: var(--mint); }
.footer-main { padding: 44px 0; display: grid; grid-template-columns: 1fr 1fr 1fr; align-items: start; gap: 30px; }
.footer-main p { font-size: 13px; line-height: 1.9; color: var(--quiet); }
.footer-main nav { display: flex; flex-direction: column; align-items: flex-start; gap: 15px; font-size: 12px; justify-self: end; }
.footer-bottom { border-top: 1px solid #c8d2c4; display: flex; justify-content: space-between; align-items: center; gap: 20px; padding: 24px 0; color: var(--quiet); font-size: 10px; }
.footer-bottom > span:nth-child(2) { font-size: 9px; }

@media (min-width: 1600px) {
  .hero { min-height: 870px; }
  .section-rail, .site-header, .site-footer, .projects-rail { padding-left: max(5.5%,calc((100vw - 1450px)/2)); padding-right: max(5.5%,calc((100vw - 1450px)/2)); }
