  .brand-spark { font-size: 26px; }
  .desktop-nav, .header-cta { display: none; }
  .menu-toggle { display: grid; place-items: center; width: 44px; height: 44px; border: 1px solid var(--line); border-radius: 5px; background: transparent; }
  .mobile-nav { position: absolute; top: 79px; left: 0; right: 0; padding: 15px 6% 25px; background: var(--paper); border-bottom: 1px solid var(--line); box-shadow: 0 14px 20px #19221e0c; }
  .mobile-nav a { display: flex; justify-content: space-between; padding: 15px 0; font-size: 14px; }
  .hero { padding: 27px 6% 0; min-height: calc(100dvh - 80px); }
  .eyebrow { font-size: 8px; letter-spacing: .65px; gap: 7px; }
  .hero-coordinate { display: none; }
  .hero-title-wrap { margin-top: 30px; }
  h1 { font-size: clamp(40px, 9vw, 64px); letter-spacing: -.05em; }
  .hero-sub { font-size: clamp(18px, 4.2vw, 24px); margin-top: 10px; }
  .idea-symbol { width: 78px; height: 78px; right: 2%; top: 93px; }
  .idea-symbol svg { width: 62px; height: 62px; }
  .idea-symbol:before, .idea-symbol:after { width: 47px; height: 4px; }
  .idea-symbol span { display: none; }
  .click-word svg { height: 12px; bottom: -5px; }
  .hero-bottom { grid-template-columns: 1fr; gap: 29px; margin-top: 36px; margin-bottom: 26px; }
  .hero-description > p:first-child { font-size: 13px; line-height: 1.85; }
  .hero-promise { font-size: 18px; margin-top: 18px; }
  .hero-actions { grid-template-columns: 1fr 1fr; gap: 10px; }
  .hero-actions .button { padding: 15px 13px; gap: 8px; font-size: 12px; }
  .hero-actions .button svg { width: 18px; }
  .action-note { grid-column: 1/-1; margin-top: 4px; font-size: 9px; }
  .hero-foot { padding: 19px 0; }
  .hero-foot a { font-size: 9px; }
  .hero-foot > span { display: none; }
  .section-rail { padding: 55px 6%; }
  .section-label { font-size: 9px; letter-spacing: .8px; margin-bottom: 32px; padding-bottom: 18px; }
  .section-label > span:last-child { display: none; }
  h2 { font-size: 45px; }
  .value-grid { grid-template-columns: 1fr; gap: 36px; }
  .value-copy > p { font-size: 13px; margin-top: 20px; max-width: none; }
  .connection-exhibit img { aspect-ratio: 1.4; }
  .section-heading-row { flex-direction: column; align-items: start; gap: 23px; }
  .section-heading-row > p { font-size: 12px; }
  .steps-list { grid-template-columns: 1fr; margin-top: 30px; }
  .steps-list li, .steps-list li + li { border-left: 0; padding: 20px 0 29px; }
  .step-marker > span { font-size: 29px; }
  .steps-list h3 { margin-top: 10px; font-size: 24px; }
  .steps-list p { max-width: none; margin-top: 13px; }
  .principle { margin-top: 0; align-items: start; font-size: 10px; line-height: 1.8; }
  .principle .status-dot { margin-top: 5px; }
  .participation-section { padding-top: 12px; }
  .gallery-grid { grid-template-columns: 1fr; gap: 16px; margin-top: 30px; }
  .gallery-copy h3 { font-size: 20px; }
  .gallery-note { font-size: 10px; margin-top: 22px; }
  .hero-feature { margin: 30px 0 0; }
  .hero-feature img { aspect-ratio: 16/10; }
  .hero-feature figcaption strong { font-size: 14px; }
  .projects-rail { padding: 55px 6%; }
  .projects-heading-row { flex-direction: column; align-items: start; gap: 23px; }
  .projects-list { gap: 44px; margin-top: 38px; }
  .project-item { grid-template-columns: 1fr; gap: 22px; }
  .project-reverse .project-media { order: 0; }
  .project-copy h3 { font-size: 27px; }
  .project-meta { grid-template-columns: 1fr; gap: 22px; }
  .projects-note { font-size: 10px; margin-top: 38px; }
  .explorer-grid, .contribution-grid, .related-grid { grid-template-columns: 1fr; gap: 16px; margin-top: 30px; }
  .explorer-card, .contribution-card, .related-card { padding: 22px; }
  .explorer-card h3, .related-card h3 { font-size: 19px; }
  .participation-grid { grid-template-columns: 1fr; margin-top: 28px; gap: 16px; }
  .participation-path { padding: 27px; }
  .participation-path h3 { font-size: 37px; margin-top: 28px; letter-spacing: -1.8px; }
  .participation-note { font-size: 10px; }
  .business-layout { grid-template-columns: 1fr; gap: 27px; }
  .business-section .section-rail { padding-bottom: 104px; }
  .business-intro > p { max-width: none; }
  .business-intro .button { max-width: none; }
  .business-benefits { padding-top: 0; }
  .business-benefits article { gap: 16px; padding: 24px 0; }
  .business-watermark { font-size: 180px; bottom: -10px; letter-spacing: -6px; }
  .faq-layout { grid-template-columns: 1fr; gap: 30px; }
  .faq-layout > div:first-child p { margin-top: 19px; }
  .faq-item h3 { font-size: 15px; }
  .faq-item p { font-size: 12px; }
  .page-hero-bottom { grid-template-columns: 1fr; gap: 28px; }
  .prepare-grid { grid-template-columns: 1fr; gap: 28px; }
  .next-cards { grid-template-columns: 1fr; }
  .participation-pilot { flex-direction: column; align-items: start; gap: 18px; }
  .pilot-form-card { padding: 24px; }
  .form-field-row { grid-template-columns: 1fr; }
  .not-found-actions .button { min-width: 0; width: 100%; }
  .site-footer { padding: 0 6%; }
  .footer-invite { padding: 37px 0; gap: 18px; }
  .footer-invite p { font-size: 27px; letter-spacing: -.9px; }
  .footer-invite > a { width: 53px; height: 53px; }
  .footer-invite > a svg { width: 28px; }
  .footer-main { grid-template-columns: 1fr 1fr; gap: 23px; padding: 32px 0; }
  .footer-main .wordmark { grid-column: 1/-1; }
