@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *:before, *:after { transition: none !important; animation: none !important; }
}

/* Original hago.click motion layer. Content remains visible without JS. */
.click-connections { display:block; width:min(100%,720px); height:auto; margin:0 auto 40px; }
.click-connections .route { fill:none;stroke:#427b68;stroke-width:2;stroke-dasharray:5 9; }
.click-connections .pulse { fill:none;stroke:#93dfbd;stroke-width:4;stroke-linecap:round;stroke-dasharray:20 300;animation:click-flow 4.8s linear 1 forwards; }
.click-connections .label { font:14px system-ui,sans-serif;fill:#1a2823; }
@keyframes click-flow { to { stroke-dashoffset:-320; } }
.project-media { overflow:hidden; }
.project-media img { transition:transform 400ms cubic-bezier(.2,.65,.3,1); }
.project-copy h3 { text-wrap:balance; }
.project-meta-label { letter-spacing:.09em; }
@media (hover:hover) and (pointer:fine) {
  .project-item:hover .project-media img { transform:scale(1.025); }
  .steps-list li { transition:background-color 200ms ease; }
  .steps-list li:hover { background-color:rgba(151,232,190,.08); }
}
.project-item:focus-within .project-media img { transform:scale(1.025); }
@media (max-width:600px) {
  .click-connections { margin-bottom:28px; }
  .click-connections .label { font-size:18px; }
}
@media (prefers-reduced-motion:reduce) {
  html { scroll-behavior:auto; }
  .click-connections .pulse { animation:none;stroke-dasharray:none;opacity:.4; }
  .project-media img,.steps-list li { transition:none; }
  .project-item:hover .project-media img,.project-item:focus-within .project-media img { transform:none; }
}

/* Contrast correction: desktop active navigation on ivory. */
.desktop-nav a.active { color:#285e49; text-decoration:underline; text-underline-offset:6px; text-decoration-thickness:1px; }

/* Editorial project gallery: three stories visible together on desktop. */
.projects-rail { padding-top:64px; padding-bottom:64px; }
.projects-list { grid-template-columns:repeat(3,minmax(0,1fr)); gap:28px; margin-top:36px; }
.project-item { display:flex; flex-direction:column; align-items:stretch; gap:26px; min-width:0; }
.project-reverse .project-media { order:0; }
.project-media img { aspect-ratio:4/3; }
.project-media figcaption { align-items:flex-start; line-height:1.6; }
.project-stage-dot { margin-top:5px; }
.project-copy h3 { font-size:clamp(25px,2.3vw,34px); line-height:1.12; margin-top:12px; }
.project-copy > p { font-size:14px; line-height:1.75; max-width:none; }
.project-meta { grid-template-columns:1fr; gap:20px; margin-top:22px; padding-top:20px; }
.projects-heading-row > p { font-size:14px; }
.projects-note { margin-top:36px; }
.gallery-media { aspect-ratio:16/9; }
.section-rail { padding-top:64px; padding-bottom:64px; }
@media (min-width:1100px) {
 .project-meta { grid-template-columns:1fr 1fr; gap:18px; }
 .project-item + .project-item { border-left:1px solid var(--dark-line); padding-left:28px; }
 .hero-feature img { aspect-ratio:2.8; }
}
@media (max-width:899px) {
