 .hero-feature { grid-column:2; grid-row:2/4; margin:0 0 38px; display:flex; flex-direction:column; justify-content:center; position:relative; }
 .hero-feature img { width:100%; height:auto; aspect-ratio:5/4; object-fit:cover; object-position:50% 35%; border-radius:2px; }
 .hero-feature figcaption { padding-top:16px; }
 .hero-feature figcaption strong { font-size:14px; max-width:380px; line-height:1.5; }
 .hero-foot { grid-column:1/-1; width:100%; margin-top:0; }
}
